import React from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';

const Navbar = ({ isAuthenticated, onLogout }) => {
  const navigate = useNavigate();
  const location = useLocation();

  const handleScroll = (elementId) => {
    if (location.pathname !== '/') {
      navigate('/', { state: { scrollTo: elementId } });
      return;
    }
    const element = document.getElementById(elementId);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <header className="navbar-header">
      <div className="container navbar-container">
        <Link to="/" className="navbar-brand">
          <span className="brand-title">KARPAGAM TRADERS</span>
          <span className="brand-tagline">Sivakasi Printing Experts</span>
        </Link>
        <nav>
          <ul className="navbar-menu">
            <li>
              <button 
                onClick={() => handleScroll('hero')} 
                className="navbar-link active" 
                style={{ background: 'none', border: 'none', cursor: 'pointer' }}
              >
                Home
              </button>
            </li>
            <li>
              <button 
                onClick={() => handleScroll('showcase')} 
                className="navbar-link" 
                style={{ background: 'none', border: 'none', cursor: 'pointer' }}
              >
                Calendars
              </button>
            </li>
            <li>
              <button 
                onClick={() => handleScroll('contact')} 
                className="navbar-link" 
                style={{ background: 'none', border: 'none', cursor: 'pointer' }}
              >
                Inquire
              </button>
            </li>
            {isAuthenticated ? (
              <>
                <li>
                  <Link to="/dashboard" className="navbar-link">Dashboard</Link>
                </li>
                <li>
                  <button 
                    onClick={onLogout} 
                    className="navbar-btn-admin"
                    style={{ cursor: 'pointer' }}
                  >
                    Logout
                  </button>
                </li>
              </>
            ) : (
              <li>
                <Link to="/login" className="navbar-btn-admin">Admin Portal</Link>
              </li>
            )}
          </ul>
        </nav>
      </div>
    </header>
  );
};

export default Navbar;
